function renderTemplates(){$('#main').innerHTML=heading('TEMPLATES & PROMPTS','为创作，建立稳定的起点。','提示词与验收规则按版本保存，旧实验始终保留原配置。',`<button class="button primary" data-edit-template="new">${icon('plus')}新建模板</button>`)+`<div class="grid3">${state.boot.templates.map(t=>`<article class="card template-card"><div class="template-preview">${icon(t.kind==='image'?'person':'play')}</div><div class="card-head"><h3>${esc(t.name)}</h3><span class="pill neutral">v${t.version}</span></div><p>${esc(t.description)}</p><div class="timeline-summary"><span class="pill ${t.kind==='image'?'orange':'blue'}">${t.kind==='image'?'图片':'视频'}</span><span class="pill neutral">${esc(t.category)}</span></div><div class="row-actions"><button class="button small" data-edit-template="${t.id}">编辑与版本</button><button class="button small" data-template-use="${t.id}">使用模板 ↗</button></div></article>`).join('')}</div><div class="notice">模板只提供约束与参考，不保证每次一致。若需要姿势图或动作视频，请在素材库上传有使用授权的实际素材。</div>`}
function renderWorkflows(){$('#main').innerHTML=heading('SKILLS & WORKFLOWS','让每一步，都清晰可控。','固定编排不额外消耗规划模型。图片与视频之间保留人工确认。')+`<div class="card"><div class="card-head"><div><h2>穿搭图 → 动态展示</h2><p>工作流 v1.0 · 后端执行，任务状态持久化。</p></div><span class="pill green">可运行模拟测试</span></div><div class="workflow-stages">${[['input_validate','校验素材',false],['outfit_image','多图穿搭',true],['asset_finalize','保存图片',false],['human_review','用户确认',false],['outfit_video','动态展示',true],['asset_finalize','保存与评分',false]].map(([id,n,ai],i)=>`<div class="workflow-stage ${ai?'ai':''}"><span class="pill ${ai?'orange':'neutral'}">${ai?'AI 调用':'固定规则'}</span><strong>${String(i+1).padStart(2,'0')} ${n}</strong><small>${id}</small></div>`).join('')}</div><p class="hint">图片和视频为关联的独立任务。视频失败复用图片，保存失败只重新保存；生成提交异常进入待核对，禁止自动重提。</p><div class="row-actions"><a class="button" href="#studio">测试工作流 ↗</a><a class="button" href="#templates">编辑模板与提示词</a></div></div><div class="notice blue">工作流由我们的服务器执行，GitHub Actions 只负责程序部署。任务恢复、预算记录和素材隐私由后端统一管理。</div><div class="grid3">${state.boot.skills.map(s=>`<article class="skill-tile"><div class="card-head"><h3>${esc(s.name)}</h3><span class="pill ${s.deferred?'neutral':s.ai?'orange':'green'}">${s.deferred?'后续':s.ai?'模型生成':'规则执行'}</span></div><code>${s.id}</code><p>${esc(s.description)}</p></article>`).join('')}</div>`}
function metrics(){const live=state.jobs.filter(j=>j.body.mode==='live'),rated=live.filter(j=>j.review&&j.review.verdict!=='pending'),passed=rated.filter(j=>j.review.verdict==='pass'),unknown=live.filter(j=>j.actual===null),spend=live.reduce((s,j)=>s+(j.actual??0),0);return {live,rated,passed,unknown,spend}}
function feedRows(compare){const prefix=compare?'compare':'job',f=state.filters;return state.jobs.filter(j=>(!compare||j.outputs?.length)&&(!f[prefix+'Mode']||f[prefix+'Mode']==='all'||j.body.mode===f[prefix+'Mode'])&&(!f[prefix+'Kind']||f[prefix+'Kind']==='all'||j.body.kind===f[prefix+'Kind'])&&(!f[prefix+'Provider']||f[prefix+'Provider']==='all'||j.body.model_snapshot.provider===f[prefix+'Provider'])&&`${j.body.label} ${j.body.group} ${j.body.model_id} ${j.body.model_snapshot.name} ${j.body.resolution} ${j.id}`.toLowerCase().includes((f[prefix+'Query']||'').toLowerCase()))}
function feedFilters(prefix){const f=state.filters;return `<div class="toolbar feed-filters"><input id="${prefix}-search" placeholder="搜索模型、清晰度、实验或对照组（回车筛选）" value="${esc(f[prefix+'Query']||'')}" aria-label="搜索${prefix==='compare'?'结果':'任务'}"><select id="${prefix}-kind" aria-label="生成类型">${[['all','图片与视频'],['image','图片'],['video','视频']].map(([k,n])=>`<option value="${k}" ${k===(f[prefix+'Kind']||'all')?'selected':''}>${n}</option>`).join('')}</select><select id="${prefix}-mode" aria-label="执行模式">${[['all','全部生成'],['live','真实AI生成'],['mock','模拟结果']].map(([k,n])=>`<option value="${k}" ${k===(f[prefix+'Mode']||'all')?'selected':''}>${n}</option>`).join('')}</select><select id="${prefix}-provider" aria-label="平台筛选"><option value="all">全部平台</option>${state.boot.providers.map(p=>`<option value="${p.id}" ${p.id===f[prefix+'Provider']?'selected':''}>${esc(p.name)}</option>`).join('')}</select>${loopControl()}</div>`}
function resultCard(j){const a=asset(j.outputs?.[0]),request=j.body.request_endpoint;return `<article class="card result-row compare-card" data-result-id="${j.id}"><div class="result-media">${a?j.outputs.map(id=>`<div class="asset-image">${media(asset(id),'',true)}</div>`).join(''):`<div class="preview-placeholder">${icon(j.body.kind==='video'?'play':'shirt')}<span>${esc(statuses[j.state]?.[0]||j.state)} · 暂无结果预览</span></div>`}</div><div class="result-details"><div class="card-head"><h3>${esc(j.body.label||j.body.model_snapshot.name)}</h3>${badge(j.state)}</div><p class="small-note">${date(j.created)} · ${esc(j.body.group||'未分组')} · ${j.body.mode==='mock'?'模拟结果':'AI生成'}</p>${jobTags(j)}<div class="cost-detail">${costSummary(j)}</div><dl class="result-facts"><dt>模型标识</dt><dd>${esc(j.body.model_snapshot.model)}</dd><dt>接口</dt><dd>${request?esc(request.method+' '+request.url):esc(providerName(j.body.model_snapshot.provider)+' / '+j.body.model_snapshot.adapter)}</dd><dt>模板</dt><dd>${esc(j.body.template_id)} v${j.body.template_version} · ${esc(j.body.prompt_version)}</dd><dt>任务编号</dt><dd>${esc(j.id)}</dd></dl>${scoreRow(j)}${j.error?`<p class="notice">${esc(j.error)}</p>`:''}<p class="small-note">${esc((j.review?.issues||[]).join('、'))} ${esc(j.review?.notes||'')}</p><div class="row-actions"><button class="button small" data-job="${j.id}">详情 / 评分与账单</button>${a?compareButton(j):''}${a?`<a class="button small" href="${esc(a.download_url)}">下载</a>`:''}</div></div></article>`}
function refreshResults(compare){if(!compare){const v=metrics(),cards=$$('#main .metric'),values=[v.live.length,v.rated.length?Math.round(v.passed.length/v.rated.length*100)+'%':'—',money(v.spend),!v.unknown.length&&v.passed.length?money(v.spend/v.passed.length):'—'];cards.forEach((c,i)=>c.querySelector('strong').textContent=values[i]);if(cards[2])cards[2].querySelector('p').textContent=`${v.unknown.length} 条待核对；含回传用量计算金额`}const root=$('#result-feed');if(!root)return;const rows=feedRows(compare),ids=new Set(rows.map(j=>j.id));$$('[data-result-id]',root).forEach(el=>{if(!ids.has(el.dataset.resultId))el.remove()});root.querySelector('.empty-state')?.remove();for(const j of rows){const fingerprint=JSON.stringify([j.updated,j.actual,j.review,j.reported_usage,j.auto_billing,j.state,j.outputs,j.outputs?.map(id=>asset(id)?.details)]);let el=root.querySelector(`[data-result-id="${j.id}"]`);if(!el||el.dataset.fingerprint!==fingerprint){const holder=document.createElement('div');holder.innerHTML=resultCard(j);const next=holder.firstElementChild;next.dataset.fingerprint=fingerprint;if(el&&JSON.stringify(j.outputs)===el.dataset.outputs){el.querySelector('.result-details').replaceWith(next.querySelector('.result-details'));el.dataset.fingerprint=fingerprint}else{if(el)el.replaceWith(next);el=next}}el.dataset.outputs=JSON.stringify(j.outputs);const position=rows.indexOf(j);if(root.children[position]!==el)root.insertBefore(el,root.children[position]||null)}if(!rows.length)root.innerHTML=empty('compare','暂无符合筛选的结果',compare?'生成的图片和视频会自动显示在这里。':'调整筛选或从创作台创建任务。')}
function renderJobs(){const v=metrics();$('#main').innerHTML=heading('EXPERIMENT NOTEBOOK','每一次测试，都有迹可循。','左侧预览结果，右侧记录模型、生成规格、质量与费用。',`<a class="button" href="/api/export?format=csv">导出 CSV</a><a class="button" href="/api/export?format=json">导出 JSON</a>`)+`<div class="grid4"><div class="metric"><small>真实调用记录</small><strong>${v.live.length}</strong></div><div class="metric"><small>人工合格率</small><strong>${v.rated.length?Math.round(v.passed.length/v.rated.length*100)+'%':'—'}</strong></div><div class="metric"><small>已登记模型费用</small><strong>${money(v.spend)}</strong><p>${v.unknown.length} 条待核对；含回传用量计算金额</p></div><div class="metric"><small>每条合格结果成本</small><strong>${!v.unknown.length&&v.passed.length?money(v.spend/v.passed.length):'—'}</strong></div></div>${feedFilters('job')}<div id="result-feed" class="result-feed"></div>`;refreshResults(false)}
function renderCompare(){$('#main').innerHTML=heading('RESULT GALLERY','每个结果，自动展开。','图片与视频自动汇集；按平台、类型、模式或关键词筛选，直接查看效果与费用。')+`<div class="toolbar"><span class="pill orange">已加入 ${state.compareIds.size} 条</span><button class="button primary" data-compare-open>并排对比已选结果</button><button class="button" data-compare-clear>清空对比选择</button></div>`+feedFilters('compare')+`<div id="result-feed" class="result-feed"></div>`;refreshResults(true)}
function renderSettings(){$('#main').innerHTML=heading('PROVIDERS & CONNECTIONS','模型可以换，工作流由我们掌握。','凭证只在服务器保存。配置状态不代表权限、余额或效果已经实测。')+`<div class="studio-grid"><section class="card"><div class="card-head"><h2>国内平台连接</h2><span class="pill ${state.boot.live_enabled?'orange':'neutral'}">${state.boot.live_enabled?'真实调用已开启':'仅模拟模式'}</span></div>${state.boot.providers.map(p=>`<div class="provider-row"><div class="provider-icon">${esc(p.name[0])}</div><div><h3>${esc(p.name)}</h3><p>${esc(p.base)}<br>服务器变量 ${p.key_env}</p></div><span class="pill ${p.configured?'green':'neutral'}">${p.configured?'Key 已配置':'待配置'}</span></div>`).join('')}<div class="notice">在服务器的 .env 中填写 Key，重启服务后生效。网页不会读取或保存完整 Key。图片可按接口内联；视频/音频一般由供应商访问公网签名URL，不需要模型Key发到网页。</div></section><section class="card"><h2>调用边界</h2><div class="provider-row"><div><h3>每日调用与预算限制</h3><p>每日次数和累计预算均不限制；单次生成仍确认费用。</p></div><span class="pill green">已解除</span></div><a class="button small" href="#jobs">查看费用记录 ↗</a></section></div><div class="card workflow-card"><div class="card-head"><h2>模型能力档案</h2><span class="pill neutral">核对日期 2026-09-30</span></div><div class="table-wrap"><table><thead><tr><th>模型</th><th>输入模式</th><th>素材能力</th><th>规格 / 刊例价格</th><th>接入状态</th><th>资料</th></tr></thead><tbody>${state.boot.models.map(m=>`<tr><td>${esc(providerName(m.provider))}<br>${esc(m.name)}<br><span class="muted">${esc(m.model)}</span></td><td>${Object.values(m.modes).map(x=>esc(x.label)).join(' / ')}</td><td>图片 ≤${m.max_images}${m.video_max?'<br>视频 ≤'+m.video_max+'秒':''}${m.audio_max?'<br>音频 ≤'+m.audio_max+'秒':''}</td><td>${esc(m.resolutions.join(' / '))}<br>${m.durations.length?`${m.durations[0]}～${m.durations.at(-1)}s`:'跟随输入 / 上游固定'}<br>${esc(priceInfo(m))}</td><td>${esc(m.verified)} / 待真实验证</td><td><a href="${esc(m.docs)}" target="_blank" rel="noreferrer">官方文档 ↗</a></td></tr>`).join('')}</tbody></table></div></div>`}
function dialog(title,content,actions=''){ $('#dialog-body').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-button" data-close aria-label="关闭">×</button></div><div class="dialog-content">${content}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!$('#dialog').open)$('#dialog').showModal();}
function closeDialog(){$('#dialog').close()}
let pickerContext=null;
function picker(context=null){pickerContext=context;const personal=context?.target==='personal',library=state.route!=='studio'&&!personal,kinds=personal?['image']:library?['image','video','audio','file']:inputKinds().filter(canAddKind);const formats={image:'.jpg,.jpeg,.png,.webp',video:'.mp4,.mov',audio:'.mp3,.wav',file:'.pdf,.txt,.md,.docx,.xlsx,.pptx'};const capacity=personal?1:library||state.draft.reference_board?50:Object.entries(currentModel().modes[state.draft.video_mode].limits).reduce((n,[u,max])=>n+Math.max(0,max-(inputCheck().counts[u]||0)),0);dialog(personal?'从素材库选择'+(context.key==='face_asset_id'?'外貌照片':'全身照片'):'添加你的素材',`<label class="upload-zone" id="drop-zone">${icon('upload')}<h3>上传新素材，或从下面选择</h3><p>${personal?'选择一张参考照片':library?'上传到素材库，独立保存':'仅接受当前模式允许的类型与数量'} · ≤200MB</p><input id="upload-input" type="file" accept="${kinds.map(k=>formats[k]).filter(Boolean).join(',')}" ${capacity>1?'multiple':''} class="hidden"></label><div class="field upload-origin"><label for="upload-origin">本次上传来源（由上传者标记）</label><select id="upload-origin"><option value="self">本人上传</option><option value="user">用户提供的素材</option></select></div><div class="toolbar picker-toolbar"><input id="picker-query" type="search" placeholder="搜索素材名称或模型" aria-label="搜索素材库"><select id="picker-kind" aria-label="筛选素材库类型"><option value="all">全部可用类型</option>${kinds.map(k=>`<option value="${k}">${{image:'图片',video:'视频',audio:'音频',file:'文档'}[k]}</option>`).join('')}</select><select id="picker-source" aria-label="筛选素材库来源"><option value="all">全部来源</option><option value="upload">上传素材</option><option value="generated">AI生成</option><option value="mock_generated">模拟结果</option><option value="demo">示例素材</option></select></div><p class="hint">${personal?'仅选择当前参考位置，不会加入穿搭任务；照片作用由外貌、发型与体型开关决定。':'首尾帧将依次分配到独立位置；名额已满或不兼容的素材不可加入。'}</p>${!personal&&!library&&state.draft.kind==='video'?`<label class="checkbox"><input type="checkbox" id="picker-outfits" ${state.videoLibraryDefault?'checked':''}>优先选择AI生成的完整穿搭图（取消可查看全部素材）</label>`:''}<div class="picker-grid" id="picker-results"></div>`);const draw=()=>{$('#picker-results').innerHTML=state.assets.filter(a=>!hiddenAsset(a)&&kinds.includes(a.kind)&&(!(!personal&&!library&&state.draft.kind==='video'&&state.videoLibraryDefault)||a.provenance?.type==='generated'&&a.provenance?.purpose==='outfit')&&($('#picker-kind').value==='all'||a.kind===$('#picker-kind').value)&&($('#picker-source').value==='all'||a.provenance?.type===$('#picker-source').value)&&`${a.name} ${a.provenance?.model_name||''}`.toLowerCase().includes($('#picker-query').value.toLowerCase())).map(a=>{const reason=personal||library?'':refProposal({asset_id:a.id,role:a.kind==='image'?'look':a.kind==='audio'?'audio':a.kind==='file'?'document':'motion'}).error;return `<button class="pick" data-pick="${a.id}" ${reason?'disabled':''} title="${esc(reason||'选择此素材')}">${media(a)}<p>${esc(a.name)}</p><small>${esc({upload:'上传素材',generated:'AI生成',mock_generated:'模拟结果',demo:'示例素材'}[a.provenance?.type]||'素材')} · ${esc(fileSpec(a))} · ${purposeLabel(a)}</small>${reason?`<small>${esc(reason)}</small>`:''}</button>`}).join('')||'<p class="hint">没有符合条件的素材，调整筛选或上传照片。</p>';};draw();$('#picker-outfits')?.addEventListener('change',e=>{state.videoLibraryDefault=e.target.checked;draw()});$('#picker-query').addEventListener('input',draw);$('#picker-kind').addEventListener('change',draw);$('#picker-source').addEventListener('change',draw);const z=$('#drop-zone');z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('drag')});z.addEventListener('dragleave',()=>z.classList.remove('drag'));z.addEventListener('drop',async e=>{e.preventDefault();await uploadFiles(e.dataTransfer.files)});}

function addReference(ref){const next=refProposal(ref);if(next.error){toast(next.error,true);return false}state.draft.refs.push(next.ref);state.draft.image_confirmed=false;return true;}
function addRef(a){if(!a)return false;let role=a.kind==='audio'?'audio':a.kind==='file'?'document':a.kind==='video'?'motion':state.draft.kind==='video'||currentModel().adapter==='mini_image'?'look':['upper','lower','shoes'].find(r=>!state.draft.refs.some(x=>x.role===r))||'accessory';return addReference({asset_id:a.id,role});}
function preflightFiles(files){if(pickerContext?.target==='personal'){if(files.length!==1)throw Error('这个参考位置只能选择一张图片');if(!/\.(jpg|jpeg|png|webp)$/i.test(files[0].name))throw Error('个人参考只接受图片');return;}if(state.route!=='studio')return;const refs=[...state.draft.refs],pending={};for(const [i,f] of [...files].entries()){const ext=f.name.split('.').pop().toLowerCase(),kind=/^(jpg|jpeg|png|webp)$/.test(ext)?'image':/^(mp4|mov)$/.test(ext)?'video':/^(mp3|wav)$/.test(ext)?'audio':/^(pdf|txt|md|docx|xlsx|pptx)$/.test(ext)?'file':'unknown';const id='pending-'+i;pending[id]={kind,size:f.size,duration:currentModel()[kind+'_min']||1};const next=refProposal({asset_id:id,role:kind==='image'?'look':kind==='audio'?'audio':'motion'},{...state.draft,refs},id=>pending[id]||asset(id));if(next.error)throw Error(next.error);refs.push(next.ref);}}
async function uploadFiles(files){const z=$('#drop-zone'),target=pickerContext;try{preflightFiles(files);if(z)z.classList.add('busy');let added=0;for(const f of files){const form=new FormData();form.append('file',f);form.append('origin',$('#upload-origin')?.value||'self');const a=await api('/assets',{method:'POST',body:form});state.assets.unshift(a);if(target?.target==='personal'){if(a.kind!=='image')throw Error('个人参考只能选择图片');state.personal[target.key]=a.id;}else if(state.route==='studio'&&addRef(a))added++;}pickerContext=null;closeDialog();render();toast(state.route==='studio'?`素材已保存；${added}件加入当前任务，其他素材可在素材库查看`:'素材已上传并保存')}catch(e){toast(e.message,true);if(z)z.classList.remove('busy')}}
function getPayload(){const checked=inputCheck();if(checked.errors.length||checked.missing.length)throw Error(checked.errors[0]?.message||checked.missing[0]);const d={...state.draft,refs:state.draft.refs.map(r=>({...r})),template_version:currentTemplate()?.version};delete d.personal_face_detail;for(const k of ['seed','duration','max_cost'])d[k]=Number(d[k]);return d;}
function chooseTemplate(id){state.draft.template_id=id;state.draft.prompt_override='';if(id==='full-turn-360'){const durations=WardrobeInputs.parameters(currentModel(),state.draft,asset).duration||[];state.draft.duration=durations.find(v=>v>=8&&v<=15)||durations.at(-1)||state.draft.duration;}}
function setKind(kind){state.draft.creative_options.pose='template';if(kind===state.draft.kind)return;state.draft.kind=kind;state.draft.model_id=kind==='image'?'seedream':'wan-flash';state.draft.template_id=kind==='image'?'studio-front':'gentle-turn';state.draft.prompt_override='';state.draft.reference_board=false;state.draft.personal_profile_id=null;state.draft.image_confirmed=false;state.draft.resolution=currentModel().resolutions[0];state.draft.duration=currentModel().durations[0]||3;state.draft.video_mode=currentModel().default_mode;state.draft.audio_mode=currentModel().audio_options[0];state.draft.refs=WardrobeInputs.reconcile(currentModel(),state.draft,asset);renderStudio();}
async function generate(){if(creating)return;creating=true;const button=$('[data-action="generate"]');if(button){button.disabled=true;button.textContent='正在提交…'}try{const payload=getPayload(),encoded=JSON.stringify(payload);if(lastPayload!==encoded){submittingId=WardrobeInputs.requestId();lastPayload=encoded}const j=await api('/jobs',{method:'POST',headers:{'Idempotency-Key':submittingId},body:encoded});lastPayload=null;submittingId=null;state.activeJob=j.id;await loadData();toast(payload.mode==='mock'?'模拟任务已创建':'真实任务已创建，后台执行中');}catch(e){toast(e.message,true)}finally{creating=false;renderStudio();}}
async function preview(){try{const p=await api('/preview',{method:'POST',body:JSON.stringify(getPayload())});dialog('本次请求预览',`<div class="timeline-summary">${p.stages.map(x=>`<span class="pill neutral">${esc(x)}</span>`).join('')}</div><p class="small-note">${p.estimate.estimated_cny===null?'参考价格待核对':`预计模型费用 ${money(p.estimate.estimated_cny)}`} · ${esc(p.estimate.source)}</p><p class="hint">刊例参考 ${money(p.estimate.reference_cny)} · ${esc(p.estimate.confidence)}<br>${esc((p.estimate.breakdown||[]).join('；'))}<br>${esc(p.estimate.discount_note)}<br>${esc(p.estimate.note)}</p><div class="code">${esc(JSON.stringify(p.request,null,2))}</div>${p.warnings.map(w=>`<p class="hint">${esc(w)}</p>`).join('')}`,`<button class="button" data-close>返回修改</button>`)}catch(e){toast(e.message,true)}}
async function jobDialog(id){try{const j=await api('/jobs/'+id),r=j.review||{};state.reviewContext=j.billing_context;state.reviewMock=j.body.mode==='mock';state.receiptMode=r.billing_mode||'amount';const videoFrom=j.body.kind==='image'&&r.verdict==='pass'&&j.outputs.length;dialog('实验详情与质量评估',`<div class="timeline-summary">${badge(j.state)}<span class="pill neutral">${j.body.mode==='mock'?'模拟 · 零模型费用':'真实调用'}</span><span class="pill neutral">${esc(j.body.model_snapshot.name)}</span></div>${jobTags(j)}${loopControl()}<div class="cost-detail">${costSummary(j)}</div>${j.error?`<div class="notice">${esc(j.error)}</div>`:''}${j.outputs.map(aid=>`<div class="asset-image">${media(asset(aid),'',true)}</div><a class="button small" href="${esc(asset(aid)?.download_url)}">下载原始结果</a>`).join('')}<p class="hint">任务 ${j.id}<br>供应商任务 ${esc(j.provider_task_id||'尚未取得')}<br>提示词 ${esc(j.body.prompt_version)} · 模板 v${j.body.template_version}</p><div class="events">${j.events.map(e=>`<div class="event">${esc(e.message)}<small>${esc(e.stage)} · ${date(e.created)}</small></div>`).join('')}</div>
 ${['uncertain','paused','save_failed'].includes(j.state)?`<div class="inline-form"><input id="resume-id" class="dialog-input" placeholder="供应商任务编号（仅待核对时需要）" value="${esc(j.provider_task_id||'')}"><button class="button" data-resume="${j.id}">${j.state==='save_failed'?'重试保存':'恢复查询'}</button></div>`:''}
 <h3>人工评价与账单核对</h3><p class="hint">API成功只代表生成完成；印花改变、漏单品或明显变脸应判为不合格。失败任务也要记录实际费用。</p><form id="review-form" data-jid="${j.id}"><div class="review-form">${['clothing','identity',...(j.body.kind==='video'?['motion']:[])].map((k,i)=>`<div class="field"><label>${['服装保真','身份一致','动作表现'][i]}</label><select name="${k}">${options([1,2,3,4,5],r[k]||3)}</select></div>`).join('')}<div class="field"><label>交付结论</label><select name="verdict">${[['pending','待评价'],['pass','合格'],['fail','不合格']].map(([k,v])=>`<option value="${k}" ${r.verdict===k?'selected':''}>${v}</option>`).join('')}</select></div>${[ ["background","白底一致"],["framing","构图完整"],["detail","清晰度 / 细节"] ].map(([k,n])=>`<div class="field"><label>${n}</label><select name="${k}"><option value="">待评价</option>${options([1,2,3,4,5],r[k]||'')}</select></div>`).join('')}${billingFields(j)}<div class="field full"><label>问题标签（逗号分隔）</label><input name="issues" value="${esc((r.issues||[]).join(','))}" placeholder="可点选标签，也可填写其他问题">${issueButtons(j)}</div><div class="field full"><label>评价备注</label><textarea name="notes">${esc(r.notes||'')}</textarea></div></div><div class="submit-row"><button class="button primary" type="submit">保存评分与账单</button></div></form><details><summary class="small-note">输入、配置与用量记录</summary><div class="code">${esc(JSON.stringify({input:j.body,usage:j.usage},null,2))}</div></details>`,`${videoFrom?`<button class="button primary" data-video-from="${j.outputs[0]}">生成动态展示</button>`:''}<button class="button" data-close>关闭</button>`);updateBilling()}catch(e){toast(e.message,true)}}
function templateDialog(id){const t=state.boot.templates.find(x=>x.id===id)||{id:'custom-look',name:'我的新模板',kind:'image',category:'outfit_image',description:'纯白背景展示',prompt:'背景与地面统一为纯白色（#FFFFFF），无场景、杂物、渐变和舞台光。人物全身居中，头顶和鞋底留白，固定水平镜头。保留衣服颜色、图案、轮廓及人物身份。',negative_prompt:'非白背景、背景杂物、切镜、身份漂移、服装改变、头脚截断',criteria:['纯白背景','服装保真','全身完整入镜']};dialog(id==='new'?'新建模板':'编辑模板 · 保存为新版本',`<form id="template-form"><div class="form-grid"><div class="field"><label>模板 ID（英文短横线）</label><input name="id" value="${esc(t.id)}" required ${id!=='new'?'readonly':''}></div><div class="field"><label>名称</label><input name="name" value="${esc(t.name)}" required></div><div class="field"><label>类型</label><select name="kind">${options(['image','video'],t.kind)}</select></div><div class="field"><label>技能</label><select name="category">${options(['outfit_image','garment_present','outfit_video'],t.category)}</select></div><div class="field full"><label>描述</label><input name="description" value="${esc(t.description)}"></div><div class="field full"><label>正向提示词</label><textarea name="prompt" required>${esc(t.prompt)}</textarea></div><div class="field full"><label>避免项（会附加到提示词）</label><textarea name="negative_prompt">${esc(t.negative_prompt)}</textarea></div><div class="field full"><label>验收标准（每行一条）</label><textarea name="criteria">${esc(t.criteria.join('\n'))}</textarea></div></div><div class="notice">每次保存创建新版本。已创建的任务保留旧版模板、素材与模型快照。</div><button class="button primary" type="submit">保存新版本</button></form>`)}
async function confirmDelete(aid){const a=asset(aid),links=await api('/assets/'+aid+'/bindings');dialog('删除或移出素材库',`<p>素材：${esc(a.name)}</p><p class="hint">移出素材库会隐藏选择入口，保留已有测试记录、个人形象和文件供核对；彻底删除仅适用于未绑定素材。</p><h3>绑定测试记录（${links.jobs.length}）</h3>${links.jobs.map(j=>`<div class="provider-row"><div>${esc(j.label)}<small>${esc(j.id)}</small></div><button class="button small" data-job="${j.id}">查看 / 核对</button></div>`).join('')||'<p>无绑定测试记录</p>'}<h3>绑定个人形象（${links.profiles.length}）</h3>${links.profiles.map(p=>`<p>${esc(p.name)} · ${esc(p.id)}</p>`).join('')||'<p>无绑定形象</p>'}`,`<button class="button" data-close>取消</button><button class="button" data-archive-asset="${aid}">保留记录，移出素材库</button><button class="button danger" data-confirm-delete="${aid}" ${links.jobs.length||links.profiles.length?'disabled':''}>彻底删除文件</button>`)}

document.addEventListener('click',async e=>{const image=e.target.closest('img[data-enlarge]');if(image&&!image.closest('.pick,.ref,.personal-photo')){enlargeAsset(image.dataset.enlarge);return;}const el=e.target.closest('button,a');if(!el||el.disabled)return;try{
 if(el.hasAttribute('data-close'))return closeDialog();
 if(el.dataset.issue){const input=$('#review-form [name=issues]'),items=input.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean),found=items.includes(el.dataset.issue);input.value=(found?items.filter(x=>x!==el.dataset.issue):[...items,el.dataset.issue]).join(', ');el.classList.toggle('selected',!found);return;}
 if(el.dataset.kind)return setKind(el.dataset.kind);
 if(el.dataset.template){chooseTemplate(el.dataset.template);return renderStudio()}
 if(el.dataset.removeRef!==undefined){state.draft.refs.splice(Number(el.dataset.removeRef),1);state.draft.image_confirmed=false;return renderStudio()}
 if(el.dataset.pick){if(pickerContext?.target==='personal'){const a=asset(el.dataset.pick);if(a?.kind!=='image')throw Error('个人参考只能选择图片');state.personal[pickerContext.key]=a.id;pickerContext=null;closeDialog();renderPersonal();return toast('参考照片已选择');}if(!addRef(asset(el.dataset.pick)))return;closeDialog();if(state.route!=='studio'){location.hash='studio'}else renderStudio();return toast('已加入素材，请确认它的角色')}
 if(el.dataset.useAsset){if(!addRef(asset(el.dataset.useAsset)))return;location.hash='studio';return}
 if(el.dataset.deleteAsset)return confirmDelete(el.dataset.deleteAsset);
 if(el.dataset.confirmDelete){await api('/assets/'+el.dataset.confirmDelete,{method:'DELETE'});await loadData();closeDialog();render();return toast('素材已删除')}
 if(el.dataset.personCard){const [key,value]=el.dataset.personCard.split(':');state.personal[key]=value;return renderPersonal();}
 if(el.dataset.creativeCard){const [key,value]=el.dataset.creativeCard.split(':');state.draft.creative_options[key]=value;if(key==='pose'&&value==='full-turn'){const ds=WardrobeInputs.parameters(currentModel(),state.draft,asset).duration;state.draft.duration=ds.find(x=>x>=8)||ds.at(-1)||state.draft.duration;}return renderStudio();}
 if(el.dataset.compareJob){const id=el.dataset.compareJob;state.compareIds.has(id)?state.compareIds.delete(id):state.compareIds.add(id);render();return;}
 if(el.hasAttribute('data-compare-open'))return compareDialog();
 if(el.hasAttribute('data-compare-clear')){state.compareIds.clear();return renderCompare();}
 if(el.dataset.archiveAsset){await api('/assets/'+el.dataset.archiveAsset+'?archive=true',{method:'DELETE'});await loadData();closeDialog();render();return toast('已移出素材库，记录与文件仍保留');}
 if(el.dataset.job)return jobDialog(el.dataset.job);
 if(el.dataset.resume){await api('/jobs/'+el.dataset.resume+'/resume',{method:'POST',body:JSON.stringify({provider_task_id:$('#resume-id').value})});await loadData();await jobDialog(el.dataset.resume);return toast('仅恢复查询或保存，不重新生成')}
 if(el.dataset.videoFrom){setKind('video');state.draft.refs=[];addRef(asset(el.dataset.videoFrom));state.draft.image_confirmed=true;state.draft.mode=state.jobs.find(j=>j.outputs.includes(el.dataset.videoFrom))?.body.mode||'mock';state.activeJob=null;closeDialog();location.hash='studio';renderStudio();return}
 if(el.dataset.editTemplate)return templateDialog(el.dataset.editTemplate);
 if(el.dataset.templateUse==='personal-image'){location.hash='personal';return renderPersonal()}
 if(el.dataset.templateUse){const t=state.boot.templates.find(x=>x.id===el.dataset.templateUse);setKind(t.kind);chooseTemplate(t.id);location.hash='studio';return renderStudio()}
 const action=el.dataset.action;
 if(action==='picker')return picker();if(action==='external')return externalDialog();
 if(action==='demo'){const rows=await api('/demo',{method:'POST',body:'{}'});await loadData();rows.forEach(x=>{if(!state.draft.refs.some(r=>r.asset_id===x.asset.id)&&state.draft.kind==='image')addReference({asset_id:x.asset.id,role:x.role})});render();return toast('示例插画已载入；仅用于流程验证')}
 if(action==='reset-prompt'){state.draft.prompt_override='';return renderStudio()}
 if(action==='generate')return generate();
 if(action==='preview')return preview();
 }catch(err){toast(err.message,true)}});
document.addEventListener('input',e=>{if(e.target.dataset.creative){const el=e.target;state.draft.creative_options[el.dataset.creative]=el.type==='number'||el.type==='range'?Number(el.value):el.value;const out=document.querySelector('[data-creative-value="'+el.dataset.creative+'"]');if(out)out.textContent=el.value;} if(e.target.closest('#review-form')&&['actual_cny','billed_units','rate_override','rate_note'].includes(e.target.name)){clearTimeout(billingTimer);++billingSequence;billingTimer=setTimeout(updateBilling,250)}const k=e.target.dataset.field;if(k&&e.target.tagName!=='SELECT'&&e.target.type!=='checkbox')state.draft[k]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(e.target.dataset.refKey&&e.target.tagName!=='SELECT')state.draft.refs[Number(e.target.dataset.refIndex)][e.target.dataset.refKey]=e.target.value;});
document.addEventListener('change',async e=>{const el=e.target,k=el.dataset.field;if(el.dataset.creative){const key=el.dataset.creative;state.draft.creative_options[key]=el.type==='checkbox'?el.checked:el.type==='range'||el.type==='number'?Number(el.value):el.value;if(el.type==='checkbox')renderStudio();} 
 if(k){state.draft[k]=el.type==='checkbox'?el.checked:el.value;if(k==='model_id'){const m=currentModel();state.draft.resolution=m.resolutions[0];state.draft.duration=m.durations[0]||3;state.draft.video_mode=m.default_mode;state.draft.audio_mode=m.audio_options[0];if(!m.ratios.includes(state.draft.ratio))state.draft.ratio=m.ratios[0];state.draft.refs=WardrobeInputs.reconcile(m,state.draft,asset);state.draft.image_confirmed=false;renderStudio()}else if(k==='video_mode'){state.draft.resolution=currentModel().modes[el.value].resolutions?.[0]||currentModel().resolutions[0];state.draft.duration=currentModel().modes[el.value].durations?.[0]||currentModel().durations[0]||3;state.draft.refs=WardrobeInputs.reconcile(currentModel(),state.draft,asset);state.draft.image_confirmed=false;renderStudio()}else if(['mode','reference_board','resolution','duration','audio_mode','image_confirmed','identity_consent','paid_confirmed','person_mode'].includes(k))renderStudio();}
 if(el.dataset.refKey){state.draft.refs[Number(el.dataset.refIndex)][el.dataset.refKey]=el.value;state.draft.image_confirmed=false;renderStudio();}
 if(el.dataset.roleIndex!==undefined){state.draft.refs[Number(el.dataset.roleIndex)].role=el.value;state.draft.image_confirmed=false;renderStudio();}
 if(el.id==='upload-input')return uploadFiles(el.files);
 if(el.id==='asset-kind'){state.filters.assetKind=el.value;renderAssets()}
 if(['job-mode','job-kind','job-provider','compare-mode','compare-kind','compare-provider'].includes(el.id)){const [prefix,field]=el.id.split('-');state.filters[prefix+field[0].toUpperCase()+field.slice(1)]=el.value;refreshResults(prefix==='compare')}
 if(el.id==='asset-source'){state.filters.assetSource=el.value;renderAssets()}
 if(el.hasAttribute('data-loop')){state.loopVideos=el.checked;$$('video[controls]').forEach(v=>v.loop=state.loopVideos);$$('[data-loop]').forEach(x=>x.checked=state.loopVideos)}
 if(el.closest('#review-form')&&['billing_mode','billing_unit'].includes(el.name)){const f=el.closest('form');if(el.name==='billing_mode'){if(state.receiptMode==='amount')f.elements.billed_units.value='';if(state.receiptMode==='units')f.elements.actual_cny.value='';state.receiptMode=el.value;}updateBilling();}
});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='asset-search'){state.filters.assetQuery=e.target.value;renderAssets()}if(e.key==='Enter'&&['job-search','compare-search'].includes(e.target.id)){const prefix=e.target.id.split('-')[0];state.filters[prefix+'Query']=e.target.value;refreshResults(prefix==='compare')}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,formId=f.getAttribute('id');try{if(formId==='login-form'){const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:$('#password').value})});const d=await r.json();if(!r.ok)throw Error(d.detail);$('#password').value='';await boot();}
 if(formId==='external-form'){const d=Object.fromEntries(new FormData(f));const ref={role:d.vendor_kind==='video'?'motion':d.vendor_kind==='audio'?'audio':'look',usage:'auto',vendor_kind:d.vendor_kind,vendor_active:!!d.vendor_active,trusted_original:!!d.trusted_original};if(d.duration)ref.duration=Number(d.duration);ref[d.source==='id'?'vendor_asset_id':'url']=d.value.trim();if(!addReference(ref))return;closeDialog();renderStudio();toast('已加入并分配接口用途')}
 if(formId==='review-form'){const d=Object.fromEntries(new FormData(f));for(const k of ['clothing','identity','motion','background','framing','detail'])d[k]=d[k]===''||d[k]===undefined?null:Number(d[k]);Object.assign(d,receiptPayload(f));d.issues=d.issues.split(/[,，]/).map(x=>x.trim()).filter(Boolean);await api('/jobs/'+f.dataset.jid+'/review',{method:'POST',body:JSON.stringify(d)});await loadData();closeDialog();render();toast('评价与费用记录已保存')}
 if(formId==='template-form'){const d=Object.fromEntries(new FormData(f));d.criteria=d.criteria.split('\n').filter(Boolean);await api('/templates',{method:'POST',body:JSON.stringify(d)});state.boot=await api('/bootstrap');closeDialog();render();toast('模板新版本已保存')}
 }catch(err){if(formId==='login-form')$('#login-error').textContent=err.message;else toast(err.message,true)}});
$('#menu-toggle').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));
$('#refresh').addEventListener('click',async()=>{try{await loadData();state.boot=await api('/bootstrap');render();toast('已刷新')}catch(e){toast(e.message,true)}});
$('#logout').addEventListener('click',async()=>{try{await api('/logout',{method:'POST',body:'{}'});showLogin()}catch(e){toast(e.message,true)}});
window.addEventListener('hashchange',route);
setInterval(async()=>{if(!state.boot||$('#shell').classList.contains('hidden')||refreshBusy||document.hidden)return;refreshBusy=true;try{await loadData();$('#connection').innerHTML='<i class="status-dot"></i> 已连接';if(state.route==='studio'){updatePreview();updateRecent()}else if(state.route==='personal'){updatePersonalResults()}else if(['jobs','compare'].includes(state.route)&&!$('#dialog').open&&!document.activeElement.matches('input,select'))refreshResults(state.route==='compare');}catch{ $('#connection').textContent='连接暂时中断';}finally{refreshBusy=false}},3000);
boot();


// Personal images use the same queue, adapters, usage records and file storage.
state.personal={name:'我的个人形象',face_asset_id:null,body_asset_id:null,face_mode:'photo',appearance:'',hair_mode:'photo',hairstyle:'long-straight',hair_details:'',body_mode:'values',height:165,weight:55,build:'natural',consent:false};
state.personalRun={model_id:'tx-kling-image-o1',resolution:'2K',ratio:'9:16',mode:'mock',paid_confirmed:false,max_cost:3};
let personalSubmitting=false,personalRequest=null;
function personalStudioControl(){if(state.draft.kind==='video')return '<p class="hint">个人形象先用于穿搭生图；动态展示使用已确认的完整穿搭图，避免额外人物图占用首帧位置。</p>';return `<div class="personal-link"><div class="field"><label for="studio-personal">带入已确认的个人形象</label><select id="studio-personal"><option value="">不带入 · 手动选择素材</option>${(state.profiles||[]).map(p=>`<option value="${p.id}" ${state.draft.personal_profile_id===p.id?'selected':''}>${esc(p.settings.name)}${p.mode==='mock'?' · 模拟':''}</option>`).join('')}</select></div><a class="text-button" href="#personal">建立 / 管理形象 ↗</a></div>${state.draft.personal_profile_id?'<label class="checkbox"><input type="checkbox" id="personal-face-detail" '+(state.draft.personal_face_detail?'checked':'')+'>同时加入原始脸部细节图（再占1个参考名额）</label>':''}`;}
function personalSelect(label,key,choices){const v=state.personal[key];return `<details class="personal-choice-panel" open><summary>${label} · ${esc(choices.find(x=>x[0]===v)?.[1]||v)}</summary><div class="skill-cards">${choices.map(([id,name])=>`<button class="skill-choice ${v===id?'selected':''}" data-person-card="${key}:${id}">${esc(name)} ${v===id?'✓':''}</button>`).join('')}</div><label for="p-${key}" class="small-note">列表选择</label><select id="p-${key}" data-person="${key}">${choices.map(([id,name])=>`<option value="${id}" ${v===id?'selected':''}>${esc(name)}</option>`).join('')}</select></details>`;}
function personalPhoto(key,title){const aid=state.personal[key],a=asset(aid);return `<div class="personal-photo"><label>${title}</label><button class="personal-select-preview" data-person-picker="${key}" aria-label="从素材库选择${title}">${a?media(a):icon('person')+'<span>选择参考照片</span>'}</button><p class="hint">${a?esc(a.name)+' · '+esc(fileSpec(a)):'未提供参考照片'}</p><div class="row-actions"><button class="button small" data-person-picker="${key}">从素材库选择</button><label class="button small">上传照片<input type="file" accept=".jpg,.jpeg,.png,.webp" data-person-upload="${key}" hidden></label>${a?`<button class="button small" data-person-clear="${key}">取消选择</button>`:''}</div></div>`;}

function renderPersonal(){const p=state.personal,u=state.personalRun,m=state.boot.models.find(x=>x.id===u.model_id)||state.boot.models.find(x=>x.kind==='image');u.model_id=m.id;if(!m.resolutions.includes(u.resolution))u.resolution=m.resolutions[0];if(!m.ratios.includes(u.ratio))u.ratio=m.ratios[0];$('#main').innerHTML=heading('YOUR PERSONAL REFERENCE','先建立一个属于你的形象。','外貌、发型与体型分别选择参考方式，确认一次，后续穿搭复用。')+`<div class="studio-grid"><section class="card"><div class="card-head"><div><h3>个人形象设置</h3><p>纯白底、正面全身、统一84%人物占比，穿素色基础衣裤。</p></div></div><div class="field"><label for="p-name">形象名称</label><input id="p-name" data-person="name" maxlength="80" value="${esc(p.name)}"></div><div class="personal-photos">${personalPhoto('face_asset_id','脸部 / 外貌照片（可选）')}${personalPhoto('body_asset_id','完整全身照片（可选）')}</div><p class="hint">只提供全身照时，也可从它参考脸与发型；独立脸部照片用于补充五官细节。仅凭脸部照片不能推断真实身材。</p>
<div class="section-label"><span>01 · 外貌来源</span></div>${personalSelect('外貌参考方式','face_mode',[['photo','跟随照片'],['description','按文字描述生成']])}${p.face_mode==='description'?`<div class="field"><label for="p-appearance">成人外貌描述</label><textarea id="p-appearance" data-person="appearance" maxlength="500" placeholder="例如：成年女性，自然五官……">${esc(p.appearance)}</textarea></div>`:''}
<div class="section-label"><span>02 · 发型来源</span></div>${personalSelect('发型参考方式','hair_mode',[['photo','跟随照片发型'],['template','选择提示词模板']])}${p.hair_mode==='template'?`${personalSelect('发型模板','hairstyle',state.hairstyles.map(x=>[x.id,x.name]))}<p class="hint">${esc(state.hairstyles.find(x=>x.id===p.hairstyle)?.prompt||'填写你希望的发型')}</p><div class="field"><label for="p-hair_details">发型补充（发色、刘海等）</label><input id="p-hair_details" data-person="hair_details" maxlength="300" value="${esc(p.hair_details)}" placeholder="例如：自然黑色、轻薄刘海"></div>`:''}
<div class="section-label"><span>03 · 体型来源</span></div>${personalSelect('体型参考方式','body_mode',[['photo','跟随完整全身照片'],['values','按身高体重与体态生成']])}${p.body_mode==='values'?`<div class="personal-sliders">${[['height','身高',120,220,'cm'],['weight','体重',30,200,'kg']].map(([k,n,min,max,unit])=>`<div class="field"><label for="p-${k}">${n} <output id="p-${k}-value">${p[k]} ${unit}</output></label><input type="range" id="p-${k}" data-person="${k}" min="${min}" max="${max}" step="1" value="${p[k]}"><input type="number" aria-label="${n}数值" data-person="${k}" min="${min}" max="${max}" value="${p[k]}"></div>`).join('')}${personalSelect('体态补充','build',[['natural','自然匀称'],['slim','偏纤细'],['athletic','运动结实'],['full','偏丰满']])}</div><p class="hint">身高体重用于视觉体型描述，不是精确人体测量或服装尺码预测。</p>`:''}
<label class="checkbox"><input data-person="consent" type="checkbox" ${p.consent?'checked':''}>本人参考素材已获得授权</label><div class="section-label"><span>04 · 模型与生成</span></div><div class="form-grid"><div class="field full"><label for="pr-model_id">生图平台 / 模型</label><select id="pr-model_id" data-person-run="model_id">${state.boot.models.filter(x=>x.kind==='image').map(x=>`<option value="${x.id}" ${m.id===x.id?'selected':''}>${esc(providerName(x.provider)+' · '+x.name)} · 最多${x.max_images}张图</option>`).join('')}</select></div>${[['resolution','清晰度',m.resolutions],['ratio','画幅',m.ratios],['mode','执行模式',['mock','live']]].map(([k,n,items])=>`<div class="field"><label for="pr-${k}">${n}</label><select id="pr-${k}" data-person-run="${k}">${items.map(v=>`<option value="${v}" ${u[k]===v?'selected':''}>${v==='mock'?'模拟 · 零费用':v==='live'?'真实 · API计费':esc(v)}</option>`).join('')}</select></div>`).join('')}<div class="field"><label for="pr-max_cost">本次预算（元）</label><input id="pr-max_cost" data-person-run="max_cost" type="number" min="0.01" max="1000" step="0.1" value="${u.max_cost}"></div></div><p class="hint">身份照和全身照最多2张；只传当前来源开关需要的照片。单图模型无法同时接收两张独立参考，提交前会校验。</p>${u.mode==='live'?`<label class="checkbox"><input data-person-run="paid_confirmed" type="checkbox" ${u.paid_confirmed?'checked':''}>确认本次真实调用及费用</label>`:''}<div class="submit-row"><button class="button" data-person-action="preview">预览请求与费用</button><button class="button primary" data-person-action="generate" ${personalSubmitting?'disabled':''}>${personalSubmitting?'提交中…':u.mode==='mock'?'生成模拟形象':'AI生成个人形象'}</button></div><p class="hint">保存已确认形象不再调用AI。重新生成才会产生新的模型费用。</p></section><aside><section class="card"><h3>已确认的个人形象</h3><div id="personal-profiles"></div></section><section class="card"><h3>个人形象生成记录</h3><p class="hint">确认脸部、发型、体型与全身构图后保存；模拟结果只验证流程。</p><div id="personal-results"></div></section></aside></div>`;updatePersonalResults();}
function updatePersonalResults(){const profiles=$('#personal-profiles'),results=$('#personal-results');if(!profiles||!results)return;profiles.innerHTML=(state.profiles||[]).map(p=>`<article class="personal-result">${media(asset(p.asset_id),'personal-result-image')}<h3>${esc(p.settings.name)}</h3><p class="hint">${p.mode==='mock'?'模拟形象':'AI个人形象'} · ${p.settings.body_mode==='values'?p.settings.height+'cm / '+p.settings.weight+'kg':'体型跟随全身照'} · ${esc(p.settings.hair_mode==='photo'?'发型跟随照片':state.hairstyles.find(x=>x.id===p.settings.hairstyle)?.name||p.settings.hairstyle)}</p><div class="row-actions"><button class="button small primary" data-person-use="${p.id}">带入穿搭</button><button class="button small" data-person-edit="${p.id}">调整后再生成</button><button class="button small danger" data-person-delete="${p.id}">移除形象</button></div></article>`).join('')||'<p class="hint">还没有已确认形象。</p>';results.innerHTML=state.jobs.filter(j=>j.body.personal_settings).slice(0,8).map(j=>`<article class="personal-result">${j.outputs[0]?media(asset(j.outputs[0]),'personal-result-image'):''}<div class="row-actions">${badge(j.state)}<span>${esc(j.body.personal_settings.name)}</span></div><p class="hint">${esc(j.body.model_snapshot.name)} · ${esc(j.body.resolution)} · ${money(j.actual)}${j.error?'<br>'+esc(j.error):''}</p><details><summary class="small-note">实际发送的提示词</summary><div class="code personal-prompt">${esc(j.body.compiled_prompt)}</div></details>${j.outputs[0]?`<a class="button small" href="${esc(asset(j.outputs[0])?.download_url)}">下载</a>`:''}<button class="button small" data-job="${j.id}">详情 / 费用</button>${j.state==='succeeded'&&j.outputs.length?`<button class="button small primary" data-person-save="${j.id}">确认并保存形象</button>`:''}</article>`).join('')||'<p class="hint">生成结果会在这里出现。</p>';}
function personalPayload(){const u=state.personalRun,m=state.boot.models.find(x=>x.id===u.model_id),t=state.boot.templates.find(x=>x.id==='personal-image');return {kind:'image',model_id:m.id,template_id:t.id,template_version:t.version,refs:[],mode:u.mode,resolution:u.resolution,ratio:u.ratio,duration:3,seed:42,video_mode:m.default_mode,max_cost:Number(u.max_cost),paid_confirmed:u.paid_confirmed,personal_settings:{...state.personal},label:'个人形象 · '+state.personal.name};}
function usePersonal(pid,face=false){const p=state.profiles.find(x=>x.id===pid);if(!p)return;setKind('image');let refs=state.draft.refs.filter(r=>!['identity','body'].includes(r.role));const desired=[{asset_id:p.asset_id,role:'body'}];if(face&&p.settings.face_asset_id&&p.settings.face_asset_id!==p.asset_id)desired.push({asset_id:p.settings.face_asset_id,role:'identity'});const proposed={...state.draft,refs:[...desired,...refs],person_mode:'self'};if(proposed.video_mode==='auto')proposed.video_mode=currentModel().default_mode;const checked=WardrobeInputs.check(currentModel(),proposed,asset);if(checked.errors.length)throw Error(checked.errors[0].message);state.draft.refs=proposed.refs;state.draft.personal_profile_id=pid;state.draft.personal_face_detail=face;state.draft.person_mode='self';state.draft.identity_consent=false;state.draft.image_confirmed=false;location.hash='studio';renderStudio();toast('个人形象已加入参考；请确认授权，再选择服装。');}
document.addEventListener('input',e=>{if(e.target.dataset.creative){const el=e.target;state.draft.creative_options[el.dataset.creative]=el.type==='number'||el.type==='range'?Number(el.value):el.value;const out=document.querySelector('[data-creative-value="'+el.dataset.creative+'"]');if(out)out.textContent=el.value;} const k=e.target.dataset.person;if(k){state.personal[k]=['height','weight'].includes(k)?Number(e.target.value):e.target.type==='checkbox'?e.target.checked:e.target.value;if(['height','weight'].includes(k)){const out=$('#p-'+k+'-value');if(out)out.textContent=e.target.value+(k==='height'?' cm':' kg');$$('[data-person="'+k+'"]').forEach(x=>{if(x!==e.target)x.value=e.target.value})}}if(e.target.dataset.personRun==='max_cost')state.personalRun.max_cost=Number(e.target.value);});
document.addEventListener('change',async e=>{try{const el=e.target,k=el.dataset.person;if(k){state.personal[k]=el.type==='checkbox'?el.checked:el.value||null;if(['height','weight'].includes(k))state.personal[k]=Number(el.value);if(el.tagName==='SELECT')renderPersonal();}const rk=el.dataset.personRun;if(rk){state.personalRun[rk]=el.type==='checkbox'?el.checked:el.value;if(rk==='model_id'){const m=state.boot.models.find(x=>x.id===el.value);state.personalRun.resolution=m.resolutions[0];state.personalRun.ratio=m.ratios.includes('9:16')?'9:16':m.ratios[0];}if(el.tagName==='SELECT')renderPersonal();}if(el.dataset.personUpload){const file=el.files[0];if(!file)return;const f=new FormData();f.append('file',file);f.append('origin','self');const a=await api('/assets',{method:'POST',body:f});state.assets.unshift(a);state.personal[el.dataset.personUpload]=a.id;renderPersonal();}if(el.id==='studio-personal'){if(el.value)usePersonal(el.value);else{state.draft.refs=state.draft.refs.filter(r=>!['body','identity'].includes(r.role));state.draft.personal_profile_id=null;state.draft.person_mode='default';renderStudio();}}if(el.id==='personal-face-detail')usePersonal(state.draft.personal_profile_id,el.checked);}catch(err){toast(err.message,true);}});
document.addEventListener('click',async e=>{const image=e.target.closest('img[data-enlarge]');if(image&&!image.closest('.pick,.ref,.personal-photo')){enlargeAsset(image.dataset.enlarge);return;}const el=e.target.closest('button');if(!el||el.disabled)return;try{if(el.dataset.personPicker)return picker({target:'personal',key:el.dataset.personPicker});if(el.dataset.personClear){state.personal[el.dataset.personClear]=null;return renderPersonal();}if(el.dataset.personUse)return usePersonal(el.dataset.personUse);if(el.dataset.personEdit){state.personal={...state.profiles.find(p=>p.id===el.dataset.personEdit).settings};return renderPersonal();}if(el.dataset.personDelete){await api('/personal-profiles/'+el.dataset.personDelete,{method:'DELETE'});await loadData();if(state.draft.personal_profile_id===el.dataset.personDelete){state.draft.personal_profile_id=null;state.draft.refs=state.draft.refs.filter(r=>!['body','identity'].includes(r.role));}updatePersonalResults();return;}if(el.dataset.personSave){const j=state.jobs.find(x=>x.id===el.dataset.personSave);dialog('确认个人形象',`${media(asset(j.outputs[0]),'personal-confirm')}<p class="hint">检查五官、发型、体型、完整脚部与白底构图。${j.body.mode==='mock'?'这是模拟结果，不可用于真实穿搭。':''}保存后可以反复带入穿搭，无额外AI调用。</p>`,`<button class="button" data-close>返回检查</button><button class="button primary" data-person-confirm="${j.id}">已确认，保存形象</button>`);return;}if(el.dataset.personConfirm){const j=state.jobs.find(x=>x.id===el.dataset.personConfirm);await api('/personal-profiles',{method:'POST',body:JSON.stringify({settings:j.body.personal_settings,job_id:j.id,asset_id:j.outputs[0],confirmed:true})});await loadData();closeDialog();updatePersonalResults();return toast('个人形象已保存，可带入穿搭。');}if(el.dataset.personAction){const payload=personalPayload();if(el.dataset.personAction==='preview'){const p=await api('/preview',{method:'POST',body:JSON.stringify(payload)});return dialog('个人形象请求预览',`<p class="hint">参考费用 ${money(p.estimate.estimated_cny)}</p><div class="code">${esc(p.prompt)}</div><div class="code">${esc(JSON.stringify(p.request,null,2))}</div>`);}if(personalSubmitting)return;personalSubmitting=true;renderPersonal();const encoded=JSON.stringify(payload);if(!personalRequest||personalRequest.encoded!==encoded)personalRequest={encoded,id:WardrobeInputs.requestId()};try{await api('/jobs',{method:'POST',headers:{'Idempotency-Key':personalRequest.id},body:encoded});personalRequest=null;await loadData();toast('形象任务已提交，结果将在右侧显示。');}finally{personalSubmitting=false;renderPersonal();}}}catch(err){toast(err.message,true);}});

function hiddenAsset(a){try{return !!JSON.parse(a.details||'{}').library_hidden}catch{return false}}
function purposeLabel(a){return {personal:'个人形象参考',product:'商品展示图',outfit:'完整穿搭图',outfit_video:'穿搭展示视频',image:'其他生成图片'}[a?.provenance?.purpose]||'上传素材 · 用途待指定'}
function compareButton(j){return `<button class="button small" data-compare-job="${j.id}">${state.compareIds.has(j.id)?'移出对比':'加入对比'}</button>`}
function compareDialog(){const rows=state.jobs.filter(j=>state.compareIds.has(j.id)&&j.outputs.length);if(rows.length<2)return toast('请至少加入两条结果后对比',true);dialog('已选结果对比',`<div class="comparison-columns">${rows.map(j=>`<article class="card">${j.outputs.map(id=>media(asset(id),'comparison-media',true)).join('')}<h3>${esc(j.body.label||j.body.model_snapshot.name)}</h3>${jobTags(j)}<div class="cost-detail">${costSummary(j)}</div>${scoreRow(j)}</article>`).join('')}</div>`)}
function enlargeAsset(id){const a=asset(id);if(!a)return;dialog('原图预览',`<div class="zoom-media">${media(a,'',true)}</div><p>${esc(a.name)} · ${fileSpec(a)} · ${purposeLabel(a)}</p>`,`<a class="button" href="${esc(a.download_url)}">下载原文件</a><button class="button" data-close>关闭</button>`)}
function creativeCards(key,items){const p=state.draft.creative_options;return `<div class="skill-cards">${items.map(([id,name])=>`<button class="skill-choice ${p[key]===id?'selected':''}" data-creative-card="${key}:${id}"><span>${esc(name)}</span>${p[key]===id?'✓':''}</button>`).join('')}</div>`}
function creativeControls(){const p=state.draft.creative_options,v=state.draft.kind==='video';return `<details class="creative-panel" ${p.hair_enabled||p.body_enabled||p.pose!=='template'?'open':''}><summary>可选技能 · 发型、体型与${v?'动作':'姿势'} <span>${p.hair_enabled?'发型已选 · ':''}${p.body_enabled?'体型已选 · ':''}${p.pose==='template'?'跟随模板':'自选姿态'}</span></summary><p class="hint">选项追加到实际提示词，不额外调用AI。${v?'首帧模式可能优先保留原图外观；改变发型或体型可能导致漂移。':''}${currentModel().prompt_max?'':'当前接口不接收提示词，技能描述不生效。'}</p><details ${p.hair_enabled?'open':''}><summary>发型 <label class="checkbox"><input type="checkbox" data-creative="hair_enabled" ${p.hair_enabled?'checked':''}>启用</label></summary>${p.hair_enabled?creativeCards('hairstyle',state.hairstyles.filter(x=>x.id!=='photo').map(x=>[x.id,x.name]))+`<input data-creative="hair_details" value="${esc(p.hair_details)}" placeholder="发色或自定义发型补充">`:'<p class="hint">跟随参考图或原模板。</p>'}</details><details ${p.body_enabled?'open':''}><summary>身高与体重 <label class="checkbox"><input type="checkbox" data-creative="body_enabled" ${p.body_enabled?'checked':''}>启用</label></summary>${p.body_enabled?`<div class="form-grid"><label>身高 <span data-creative-value="height">${p.height}</span> cm<input type="range" data-creative="height" min="120" max="220" value="${p.height}"></label><label>体重 <span data-creative-value="weight">${p.weight}</span> kg<input type="range" data-creative="weight" min="30" max="200" value="${p.weight}"></label></div>${creativeCards('build',[['natural','自然匀称'],['slim','偏纤细'],['athletic','运动结实'],['full','偏丰满']])}<p class="hint">数值作为视觉描述，不代表精确身体测量。</p>`:'<p class="hint">跟随参考图或原模板。</p>'}</details><details open><summary>${v?'动作':'姿势'}选择</summary>${creativeCards('pose',v?[['template','跟随模板'],['gentle-motion','轻微模特动作'],['turn','缓慢45度转身'],['full-turn','完整360度'],['calm-random','克制随机动作']]:[['template','跟随模板'],['relaxed','自然站立'],['weight-shift','轻微重心变化'],['quarter','微侧身展示'],['catalog','克制随机姿势']])}</details></details>`}
